mapper.select:
SELECT  FROM seat
WHERE room_id = #{roomId}
ORDER BY row_no, col_no

SELECT  FROM seat s
WHERE s.room_id = #{roomId}
  AND s.status = 'NORMAL'
  AND s.has_power = #{hasPower}
  AND s.near_window = #{nearWindow}
  AND s.quiet_zone = #{quietZone}
  AND NOT EXISTS (
    SELECT 1 FROM reservation r
    WHERE r.seat_id = s.id
      AND r.status IN ('RESERVED', 'IN_USE', 'LEFT_TEMP')
      AND r.start_at < #{endAt} AND r.end_at > #{startAt}
  )
ORDER BY s.row_no, s.col_no

mapper.update:
UPDATE seat
SET status = #{status},
    version = version + 1,
    updated_at = #{now}
WHERE id = #{id} AND version = #{expectedVersion}
